from functools import cache


def generate_trees(n):
    @cache
    def gen(lo, hi):
        if lo > hi:
            return [None]
        out = []
        for root in range(lo, hi + 1):
            for left in gen(lo, root - 1):
                for right in gen(root + 1, hi):
                    out.append(TreeNode(root, left, right))
        return out

    return gen(1, n) if n else []
